      `/targets${instanceId != null ? `?instance_id=${instanceId}` : ''}`
    ),
  create: (data: {
    instance_id: number
    freq_hz: number
    bandwidth_hz?: number
    label?: string
    threshold_db?: number
    enabled?: boolean
  }) =>
    request<import('../types').WatchTarget>('/targets', {
      method: 'POST',
      body: JSON.stringify(data),
    }),
  update: (id: number, data: Partial<import('../types').WatchTarget>) =>
    request<import('../types').WatchTarget>(`/targets/${id}`, {
      method: 'PUT',
      body: JSON.stringify(data),
    }),
  delete: (id: number) => request<{ ok: boolean }>(`/targets/${id}`, { method: 'DELETE' }),
}

// --- Events ---

export const events = {
  list: (params?: {
    page?: number
    page_size?: number
    instance_id?: number
    freq_min?: number
    freq_max?: number
    date_from?: string
    date_to?: string
    label?: string
  }) => {
    const searchParams = new URLSearchParams()
    if (params) {
      Object.entries(params).forEach(([k, v]) => {
        if (v != null) searchParams.set(k, String(v))
      })
    }
    const qs = searchParams.toString()
    return request<import('../types').PaginatedResponse<import('../types').DetectionEvent>>(
      `/events${qs ? `?${qs}` : ''}`
    )
  },
  stats: () => request<import('../types').EventStats>('/events/stats'),
  exportCsv: () => `${BASE}/events/export`,
}

// --- Recordings ---

export const recordings = {
  list: () => request<string[]>('/recordings'),
  url: (filename: string) => `${BASE}/recordings/${encodeURIComponent(filename)}`,
  delete: (filename: string) =>
    request<{ ok: boolean }>(`/recordings/${encodeURIComponent(filename)}`, { method: 'DELETE' }),
}

// --- Notifications ---

export const notifications = {
  list: () => request<import('../types').NotificationConfig[]>('/notifications'),
  test: (backend: string) => request<{ ok: boolean }>(`/notifications/${backend}/test`, { method: 'POST' }),
}

// --- Settings ---

export const settings = {
  get: () => request<import('../types').GlobalSettings>('/settings'),
  update: (data: Partial<import('../types').GlobalSettings>) =>
    request<import('../types').GlobalSettings>('/settings', {
      method: 'PUT',
      body: JSON.stringify(data),
    }),
}

// --- Health ---

export const health = () => request<{ status: string; version: string }>('/health')

import { useState } from 'react'
import { X, RefreshCw } from 'lucide-react'
import { instances as api } from '../../api/client'
import { UI } from '../../utils/strings'
import type { SdrInstance, AvailableProfile } from '../../types'

interface InstanceFormProps {
  instance: SdrInstance | null
  onClose: () => void
  onSaved: () => void
}

export default function InstanceForm({ instance, onClose, onSaved }: InstanceFormProps) {
  const [name, setName] = useState(instance?.name ?? '')
  const [url, setUrl] = useState(instance?.url ?? '')
  const [enabled, setEnabled] = useState(instance?.enabled ?? true)
  const [desiredProfile, setDesiredProfile] = useState<string | null>(instance?.desired_profile ?? null)
  const [profiles, setProfiles] = useState<AvailableProfile[]>([])
  const [loadingProfiles, setLoadingProfiles] = useState(false)
  const [saving, setSaving] = useState(false)
  const [error, setError] = useState<string | null>(null)

  const fetchProfiles = async () => {
    if (!instance) return
    setLoadingProfiles(true)
    try {
      const data = await api.profiles(instance.id)
      setProfiles(data)
    } catch (err: any) {
      setError(err.message)
    } finally {
      setLoadingProfiles(false)
    }
  }

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    setSaving(true)
    setError(null)
    try {
      if (instance) {
        await api.update(instance.id, { name, url, enabled, desired_profile: desiredProfile })
      } else {
        await api.create({ name, url, enabled, desired_profile: desiredProfile })
      }
      onSaved()
    } catch (err: any) {
      setError(err.message)
    } finally {
      setSaving(false)
    }
  }

  return (
    <div className="fixed inset-0 bg-black/60 z-50 flex items-center justify-center p-4">
      <form onSubmit={handleSubmit} className="card max-w-md w-full space-y-4">
        <div className="flex items-center justify-between">
          <h3 className="text-sm font-medium">
            {instance ? 'Instanz bearbeiten' : UI.cfg_add_instance}
          </h3>
          <button type="button" onClick={onClose} className="text-sdr-muted hover:text-sdr-text">
            <X className="w-4 h-4" />
          </button>
        </div>

        {error && <p className="text-sdr-red text-xs">{error}</p>}

        <div>
          <label className="label">{UI.cfg_name}</label>
          <input className="input w-full" value={name} onChange={e => setName(e.target.value)} required />
        </div>

        <div>
          <label className="label">{UI.cfg_url}</label>
          <input className="input w-full" value={url} onChange={e => setUrl(e.target.value)} placeholder="http://sdr-host:8073" required />
        </div>

        {instance && (
          <div>
            <label className="label">{UI.cfg_profile}</label>
            <div className="flex gap-2">
              <select
                className="input w-full"
                value={desiredProfile ?? ''}
                onChange={e => setDesiredProfile(e.target.value || null)}
              >
                <option value="">— kein Profil —</option>
                {profiles.map(p => (
                  <option key={p.id} value={p.id}>{p.name}</option>
                ))}
                {desiredProfile && !profiles.find(p => p.id === desiredProfile) && (
                  <option value={desiredProfile}>{desiredProfile}</option>
                )}
              </select>
              <button
                type="button"
                onClick={fetchProfiles}
                disabled={loadingProfiles}
                className="btn-ghost flex items-center gap-1 text-xs whitespace-nowrap"
              >
                <RefreshCw className={`w-3.5 h-3.5 ${loadingProfiles ? 'animate-spin' : ''}`} />
                {UI.cfg_fetch_profiles}
              </button>
            </div>
            {profiles.length === 0 && !loadingProfiles && (
              <p className="text-xs text-sdr-muted mt-1">{UI.cfg_no_profiles}</p>
            )}
          </div>
        )}

        <label className="flex items-center gap-2 text-sm cursor-pointer">
          <input type="checkbox" checked={enabled} onChange={e => setEnabled(e.target.checked)}
            className="accent-sdr-cyan" />
          {UI.cfg_enabled}
        </label>

        <div className="flex justify-end gap-2 pt-2">
          <button type="button" onClick={onClose} className="btn-ghost">{UI.cfg_cancel}</button>
          <button type="submit" disabled={saving} className="btn-primary">
            {saving ? UI.loading : UI.cfg_save}
          </button>
        </div>
      </form>
    </div>
  )
}

