import { useState } from 'react'
import { Pencil, Trash2, Plus } from 'lucide-react'
import { instances as api } from '../../api/client'
import { UI } from '../../utils/strings'
import StatusBadge from '../shared/StatusBadge'
import ConfirmDialog from '../shared/ConfirmDialog'
import InstanceForm from './InstanceForm'
import type { SdrInstance } from '../../types'

interface InstanceListProps {
  instances: SdrInstance[]
  onRefresh: () => void
}

export default function InstanceList({ instances, onRefresh }: InstanceListProps) {
  const [showForm, setShowForm] = useState(false)
  const [editing, setEditing] = useState<SdrInstance | null>(null)
  const [deleteId, setDeleteId] = useState<number | null>(null)

  const handleDelete = async () => {
    if (deleteId == null) return
    await api.delete(deleteId)
    setDeleteId(null)
    onRefresh()
  }

  return (
    <>
      <div className="flex items-center justify-between mb-3">
        <h4 className="text-sm font-medium">{UI.cfg_instances}</h4>
        <button onClick={() => { setEditing(null); setShowForm(true) }} className="btn-primary flex items-center gap-1.5">
          <Plus className="w-3.5 h-3.5" />
          {UI.cfg_add_instance}
        </button>
      </div>

      {instances.length === 0 ? (
        <p className="text-sdr-muted text-sm py-4 text-center">{UI.dash_no_instances}</p>
      ) : (
        <div className="space-y-2">
          {instances.map(inst => (
            <div key={inst.id} className="flex items-center justify-between p-3 bg-sdr-bg rounded-lg border border-sdr-border">
              <div className="flex items-center gap-3 min-w-0">
                <StatusBadge active={inst.enabled} activeText={UI.cfg_enabled} inactiveText="Deaktiviert" />
                <div className="min-w-0">
                  <p className="text-sm font-medium truncate">{inst.name}</p>
                  <p className="text-xs text-sdr-muted truncate">{inst.url}</p>
                </div>
              </div>
              <div className="flex items-center gap-1 shrink-0">
                <button
                  onClick={() => { setEditing(inst); setShowForm(true) }}
                  className="p-1.5 text-sdr-muted hover:text-sdr-text transition-colors"
                  title={UI.cfg_edit}
                >
                  <Pencil className="w-3.5 h-3.5" />
                </button>
                <button
                  onClick={() => setDeleteId(inst.id)}
                  className="p-1.5 text-sdr-muted hover:text-sdr-red transition-colors"
                  title={UI.cfg_delete}
                >
                  <Trash2 className="w-3.5 h-3.5" />
                </button>
              </div>
            </div>
          ))}
        </div>
      )}

      {showForm && (
        <InstanceForm
          instance={editing}
          onClose={() => setShowForm(false)}
          onSaved={() => { setShowForm(false); onRefresh() }}
        />
      )}

      <ConfirmDialog
        open={deleteId != null}
        message={UI.confirm_delete}
        onConfirm={handleDelete}
        onCancel={() => setDeleteId(null)}
      />
    </>
  )
}

import { useState } from 'react'
import { X } from 'lucide-react'
import { targets as api } from '../../api/client'
import { UI } from '../../utils/strings'
import FrequencyInput from '../shared/FrequencyInput'
import DecibelSlider from '../shared/DecibelSlider'
import type { SdrInstance, WatchTarget } from '../../types'

interface TargetFormProps {
  target: WatchTarget | null
  instances: SdrInstance[]
  onClose: () => void
  onSaved: () => void
}

export default function TargetForm({ target, instances, onClose, onSaved }: TargetFormProps) {
  const [instanceId, setInstanceId] = useState(target?.instance_id ?? instances[0]?.id ?? 0)
  const [freqHz, setFreqHz] = useState(target?.freq_hz ?? 145_500_000)
  const [bandwidthHz, setBandwidthHz] = useState(target?.bandwidth_hz ?? 12000)
  const [label, setLabel] = useState(target?.label ?? '')
  const [thresholdDb, setThresholdDb] = useState(target?.threshold_db ?? -55)
  const [enabled, setEnabled] = useState(target?.enabled ?? true)
  const [saving, setSaving] = useState(false)
  const [error, setError] = useState<string | null>(null)

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    setSaving(true)
    setError(null)
    try {
      if (target) {
        await api.update(target.id, {
          freq_hz: freqHz,
          bandwidth_hz: bandwidthHz,
          label,
          threshold_db: thresholdDb,
          enabled,
        })
      } else {
        await api.create({
          instance_id: instanceId,
          freq_hz: freqHz,
          bandwidth_hz: bandwidthHz,
          label,
          threshold_db: thresholdDb,
          enabled,
        })
      }
      onSaved()
    } catch (err: any) {
      setError(err.message)
    } finally {
      setSaving(false)
    }
  }

  return (
    <div className="fixed inset-0 bg-black/60 z-50 flex items-center justify-center p-4">
      <form onSubmit={handleSubmit} className="card max-w-md w-full space-y-4">
        <div className="flex items-center justify-between">
          <h3 className="text-sm font-medium">
            {target ? 'Ziel bearbeiten' : UI.cfg_add_target}
          </h3>
          <button type="button" onClick={onClose} className="text-sdr-muted hover:text-sdr-text">
            <X className="w-4 h-4" />
          </button>
        </div>

        {error && <p className="text-sdr-red text-xs">{error}</p>}

        {!target && (
          <div>
            <label className="label">SDR-Instanz</label>
            <select className="input w-full" value={instanceId} onChange={e => setInstanceId(Number(e.target.value))}>
              {instances.map(i => (
                <option key={i.id} value={i.id}>{i.name}</option>
              ))}
            </select>
          </div>
        )}

        <FrequencyInput value={freqHz} onChange={setFreqHz} label={UI.cfg_freq} />

        <div>
          <label className="label">{UI.cfg_bandwidth}</label>
          <div className="relative">
            <input
              type="number"
              step="0.1"
              value={bandwidthHz / 1000}
              onChange={e => setBandwidthHz(parseFloat(e.target.value) * 1000)}
              className="input w-full pr-12"
            />
            <span className="absolute right-3 top-1/2 -translate-y-1/2 text-xs text-sdr-muted">kHz</span>
          </div>
        </div>

        <div>
          <label className="label">{UI.cfg_label}</label>
